{
  "research": [
    {
      "id": "R1",
      "title": "Visibility-Aware Consistency for Occluded Keypoint Detection",
      "bullets": [
        "Investigated whether visibility-aware consistency improves keypoint localization under partial occlusion; developed a training objective separating visible landmarks from synthetically obscured landmarks.",
        "Evaluated localization errors across occlusion patterns and compared visibility weighting against uniform consistency penalties using controlled masking experiments."
      ]
    },
    {
      "id": "R2",
      "title": "Illumination-Robust Semantic Segmentation Through Appearance Consistency",
      "bullets": [
        "Formulated questions about illumination sensitivity in semantic segmentation and led development of feature moment perturbations, patchwise consistency objectives, and confidence-weighted training.",
        "Compared these components under held-out lighting conditions, examining classwise segmentation errors, confidence calibration, and sensitivity to appearance perturbation strength through ablation experiments."
      ]
    }
  ],
  "publications": [
    {
      "id": "P1",
      "title": "Confidence-Weighted Appearance Consistency for Semantic Segmentation Under Lighting Shifts"
    },
    {
      "id": "P2",
      "title": "Patchwise Prediction Consistency for Illumination-Robust Semantic Segmentation"
    },
    {
      "id": "P3",
      "title": "Feature Moment Perturbations for Semantic Segmentation Across Illumination Conditions"
    }
  ],
  "work": [],
  "projects": [
    {
      "id": "T1",
      "title": "Comparative Evaluation of Image Retrieval Descriptors",
      "bullets": [
        "Implemented image retrieval pipelines using color histograms and gradient descriptors, with standardized preprocessing and distance-based ranking over a shared image collection.",
        "Compared retrieval precision across descriptor choices and dimensionality reduction settings, inspecting failure cases involving viewpoint changes, background clutter, and similar color distributions."
      ]
    },
    {
      "id": "T2",
      "title": "Loss Functions for Imbalanced Image Classification",
      "bullets": [
        "Implemented a convolutional image classifier with cross-entropy, class-weighted cross-entropy, and focal loss while holding architecture and data partitions fixed.",
        "Compared per-class recall and confusion patterns under controlled class imbalance, examining how loss selection affected minority-class predictions and overall calibration."
      ]
    },
    {
      "id": "T3",
      "title": "Classical and Learned Methods for Image Denoising",
      "bullets": [
        "Implemented Gaussian filtering, nonlocal means, and a convolutional denoising autoencoder using matched clean images and synthetically corrupted inputs.",
        "Compared reconstruction quality across noise levels using peak signal-to-noise ratio and structural similarity, inspecting edge preservation and texture smoothing artifacts."
      ]
    }
  ]
}
